func (n *netbirdRollout) meshListenerLoop(ctx context.Context, localAddress func() netip.Addr, listen func(netip.Addr) (net.Listener, error), interval time.Duration) {
	var listener net.Listener
	var bound netip.Addr
	defer func() {
		if listener != nil {
			_ = listener.Close()
		}
	}()
	ticker := time.NewTicker(interval)
	defer ticker.Stop()
	last := ""
	for ctx.Err() == nil {
		address := localAddress()
		var err error
		if address != bound {
			if listener != nil {
				_ = listener.Close()
			}
			listener, bound = nil, netip.Addr{}
		}
		if address.IsValid() && listener == nil {
			listener, err = listen(address)
			if err == nil {
				bound = address
			}
		}
		if errors.Is(err, natscell.ErrBridgeClosed) {
			return
		}
		if err != nil && err.Error() != last {
			slog.WarnContext(ctx, "NetBird NATS listener held; retrying", "error", err)
		}
		last = ""
		if err != nil {
			last = err.Error()
		}
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
		}
	}
}

func newNodeOpsTest(t *testing.T) (*nodeOps, *fenceLB, *nodeInstances) {
	t.Helper()
	fence, _, balancer, _, _ := newFenceTest(t)
	// Every node serves in both sets; the default quorum guard keeps two.
	balancer.sets["ts-auth"][0] = lb.Backend{IP: fenceAddresses["ctl-1"], Port: 8080}
	spec := &cellspec.ReleaseFence{LoadBalancerID: "ocid1.loadbalancer.oc1..x",
		BackendSets: []cellspec.FencedSet{{Name: "terrabase", Port: 9465}, {Name: "ts-auth", Port: 8080}}}
	fence.spec = func() (*cellspec.ReleaseFence, map[string]string) { return spec, fenceAddresses }
	hosts := &nodeHosts{sessions: map[string]string{"ctl-1": "s1", "ctl-2": "s2", "ctl-3": "s3"}, down: map[string]bool{},
		states: map[string]string{}, withdrawn: map[string]bool{}}
	fence.hosts = hosts
	instances := &nodeInstances{hosts: hosts, lb: balancer, t: t, shape: map[string][2]float32{}}
	ops := newNodeOps(fence, func(context.Context) (nodeCompute, error) { return instances, nil }, nil)
	ops.poll = time.Millisecond
	return ops, balancer, instances
}

func (n *netbirdRollout) healthyMesh(ctx context.Context, node string, status network.Status, since time.Time, verifyLeaderPeer bool) error {
	address, err := netip.ParseAddr(status.IP)
	if !status.Connected || err != nil || !netbirdClientRange.Contains(address) || !strings.HasSuffix(status.DNS, ".nb.ts.internal") || len(status.DNS) > 255 {
		return errors.New("NetBird management, signal, mesh IP and peer DNS name are not ready")
	}
	ctx, cancel := context.WithTimeout(ctx, 8*time.Second)
	defer cancel()
	// The leader's own mesh address is locally routed. Prove a remote peer
	// too, so an isolated leader cannot confirm itself using loopback traffic.
	if verifyLeaderPeer && node == n.services.controllerNode(n.cell, n.cfg.NATS.Instance) {
		_, addresses := n.addresses()
		peers := make([]string, 0, len(addresses))
		for peer := range addresses {
			if peer != node && n.nodes != nil && n.nodes.controllers != nil && n.nodes.controllers(peer) {
				peers = append(peers, peer)
			}
		}
		slices.Sort(peers)
		if len(peers) == 0 {
			return errors.New("NetBird leader has no remote controller peer to verify")
		}
		if err := n.healthyRemotePeer(ctx, peers); err != nil {
			return err
		}
	}
	answers, err := net.DefaultResolver.LookupNetIP(ctx, "ip4", status.DNS)
	if err != nil || !slices.Contains(answers, address) {
		return errors.New("NetBird DNS answer does not contain the peer's mesh IP")
	}
	if reason, err := nodeRolesServing(ctx, n.fence.hosts, node, since); err != nil || reason != "" {
		return fmt.Errorf("node roles are not ready: %s%v", reason, errSuffix(err))
	}
	_, addresses := n.addresses()
	statuses, err := n.fence.hosts.ListHosts(ctx)
	if err != nil {
		return err
	}
	found, probed := false, false
	for _, entry := range statuses {
		if entry.Registration.Node != node {
			continue
		}
		found = true
		for _, role := range entry.Registration.Roles {
			desired, err := n.fence.hosts.ListDesired(ctx, role)
			if err != nil {
				return err
			}
			index := slices.IndexFunc(desired, func(d host.Desired) bool { return d.Node == node && !d.Withdrawn })
			if index < 0 {
				continue
			}
			switch role {
			case tsauth.Role:
				if err := meshReady(ctx, status.IP, tsauth.Port, nil); err != nil {
					return fmt.Errorf("ts-auth over NetBird: %w", err)
				}
				probed = true
			case terrabase.Role:
				profile, err := terrabase.ParseProfile(desired[index].Env)
				if err != nil {
					return err
				}
				pem, err := os.ReadFile(n.cfg.Controller.TerraBaseCACertFile)
				if err != nil {
					return err
				}
				roots := x509.NewCertPool()
				if !roots.AppendCertsFromPEM(pem) {
					return errors.New("invalid TerraBase CA")
				}
				if err := meshReady(ctx, status.IP, profile.ClientPort, &tls.Config{RootCAs: roots, ServerName: addresses[node], MinVersion: tls.VersionTLS12}); err != nil {
					return fmt.Errorf("TerraBase over NetBird: %w", err)
				}
				probed = true
			}
		}
	}
	if !found {
		return errors.New("node has no registered host session")
	}
	if n.nodes != nil && n.nodes.controllers != nil && n.nodes.controllers(node) {
		options := []nats.Option{nats.Timeout(3 * time.Second), nats.NoReconnect(), nats.TLSHandshakeFirst(),
			nats.RootCAs(n.cfg.NATS.TLS.CAFile), nats.ClientCert(n.cfg.NATS.TLS.CertFile, n.cfg.NATS.TLS.KeyFile),
			nats.SetCustomDialer(meshDialer{ctx: ctx, address: net.JoinHostPort(status.IP, "4222")}),
			nats.ErrorHandler(natscell.ErrorHandler)}
		if n.cfg.NATS.CredentialsFile != "" {
			options = append(options, nats.UserCredentials(n.cfg.NATS.CredentialsFile))
		} else {
			option, err := nats.NkeyOptionFromSeed(n.cfg.NATS.NKeySeedFile)
			if err != nil {
				return err
			}
			options = append(options, option)
		}
		conn, err := nats.Connect("tls://"+net.JoinHostPort(addresses[node], "4222"), options...)
		if err != nil {
			return errors.New("authenticated NATS over NetBird is unavailable")
		}
		defer conn.Close()
		if err := conn.FlushWithContext(ctx); err != nil {
			return err
		}
		probed = true
	}
	if !probed {
		return errors.New("NetBird peer has no active service endpoint to verify mesh traffic")
	}
	return nil
}

func (n *netbirdRollout) serveRecovery(ctx context.Context, probe func(context.Context, string) error) (*nats.Subscription, error) {
	if n.conn == nil || len(n.key) != ed25519.PrivateKeySize {
		return nil, errors.New("NetBird recovery responder needs its controller connection and signing key")
	}
	return n.conn.Subscribe(netbirdRecoverySubject(n.cell, n.cfg.NATS.Instance), func(message *nats.Msg) {
		if message.Reply == "" || ctx.Err() != nil {
			return
		}
		var envelope protocol.Envelope
		var request netbirdRecoveryRequest
		if protocol.DecodeStrict(message.Data, &envelope, netbirdRecoveryMaxBytes) != nil ||
			protocol.DecodeStrict(envelope.Payload, &request, netbirdRecoveryMaxBytes) != nil || request.Responder != n.cfg.NATS.Instance {
			return
		}
		scope, err := n.recoveryScope(request, netbirdRecoveryRequestKind, request.Requester, envelope.OperationID, envelope.Epoch)
		if err != nil || protocol.VerifyEnvelope(envelope, scope, n.key.Public().(ed25519.PublicKey), time.Now(),
			protocol.VerifyPolicy{MaxLifetime: netbirdRecoveryLifetime, ClockSkew: time.Second}) != nil {
			return
		}
		probeCtx, cancel := context.WithDeadline(ctx, envelope.ExpiresAt)
		defer cancel()
		connected := probe(probeCtx, request.Address) == nil
		if probeCtx.Err() != nil {
			return
		}
		payload, err := protocol.EncodeJSON(netbirdRecoveryProof{Request: request, Connected: connected})
		if err != nil {
			return
		}
		scope.Kind, scope.Actor = netbirdRecoveryProofKind, n.cfg.NATS.Instance
		proof, err := protocol.SignEnvelope(payload, scope, time.Now(), envelope.ExpiresAt, n.key)
		if err != nil {
			return
		}
		if wire, err := protocol.EncodeJSON(proof); err == nil {
			// Production credentials grant exactly one response for five
			// seconds after this allowed subscription receives the request.
			_ = message.Respond(wire)
		}
	})
}

func (n *netbirdRollout) recoverySSH(ctx context.Context, node, address string) error {
	if node != n.services.controllerNode(n.cell, n.cfg.NATS.Instance) {
		return netbirdSSH(ctx, address)
	}
	// A self-dial follows the local route and proves no remote OCI ingress.
	// Require another actual controller to read the target's SSH banner.
	if n.conn == nil || len(n.key) != ed25519.PrivateKeySize || n.cfg.NATS.Embedded == nil {
		return errors.New("NetBird leader requires a fresh remote controller OCI SSH recovery proof")
	}
	ctx, cancel := context.WithTimeout(ctx, 8*time.Second)
	defer cancel()
	epoch, err := n.fence.leading(ctx)
	if err != nil {
		return err
	}
	for _, slot := range n.cfg.NATS.Embedded.BrokerIDs {
		if slot == n.cfg.NATS.Instance {
			continue
		}
		request := netbirdRecoveryRequest{Requester: n.cfg.NATS.Instance, Responder: slot,
			Authority: n.fence.fencer.Current().CandidateID, Node: node, Address: address}
		scope, err := n.recoveryScope(request, netbirdRecoveryRequestKind, request.Requester, entityid.New(), epoch)
		if err != nil {
			continue
		}
		payload, err := protocol.EncodeJSON(request)
		if err != nil {
			return err
		}
		now := time.Now()
		envelope, err := protocol.SignEnvelope(payload, scope, now, now.Add(netbirdRecoveryLifetime), n.key)
		if err != nil {
			return err
		}
		wire, err := protocol.EncodeJSON(envelope)
		if err != nil {
			return err
		}
		attempt, stop := context.WithTimeout(ctx, 4*time.Second)
		reply, err := n.conn.RequestWithContext(attempt, netbirdRecoverySubject(n.cell, slot), wire)
		stop()
		if err == nil && n.verifyRecovery(reply.Data, request, scope) == nil {
			return n.fence.fencer.Guard(ctx, epoch)
		}
		if ctx.Err() != nil {
			break
		}
	}
	return fmt.Errorf("NetBird leader %s has no fresh remote controller OCI SSH recovery proof; no node will be drained", node)
}
